def require_selection(self, snapshot, owners):
    live = {thread.name for thread in OwnerRestartRequest().threads(snapshot)}
    if live != {thread.name for thread in owners} or live != {item.name for item in self.audience}:
        raise RuntimeError('Complete original owner audience changed; recapture/review required')
    for selection, original in zip(self.audience, self.originals, strict=True):
        current = selection.require_current(snapshot)
        current.require_idle()
        if current != original:
            raise RuntimeError('Original owner settings changed')
    self.cohort.require_original()
    require_no_clients(self.audience)
    InputDispositions(ROOT / InputDispositions.filename).read()
    self.task_carry.require_selection(snapshot, owners)

def require_selection(self, snapshot, owners) -> None:
    audience = {thread.name for thread in OwnerRestartRequest().threads(snapshot)}
    if {thread.name for thread in owners} != audience:
        raise RelationViolationError('Index cutover requires every managed restart owner.')
    if not self.original_python.is_absolute() or not self.original_python.is_file():
        raise RelationViolationError('Original installed writer interpreter is required.')
    WireRootIdText.from_text(self.wire_root_id)
    verify_native_package(self.native_package)
    environment = dict(os.environ)
    environment.pop('PYTHONPATH', None)
    original_schema = subprocess.run([str(self.original_python), str(Path(__file__).with_name('checkpoint_schema.py'))], env=environment, check=True, capture_output=True, text=True).stdout.strip()
    if original_schema == declared_schema_digest():
        raise RelationViolationError('Installed schemas already match; retained reset is unnecessary.')

def require_selection(self, snapshot, owners):
    live = {thread.incarnation for thread in OwnerRestartRequest().threads(snapshot)}
    if live != {thread.incarnation for thread in owners}:
        raise RelationViolationError('Task carry requires the whole live owner audience.')
    if not self.original_python.is_absolute() or not self.original_python.is_file():
        raise RelationViolationError('Original installed decoder is required.')
    if not self.receipt.is_absolute() or self.receipt.exists() or self.receipt.is_symlink():
        raise RelationViolationError('Task carry receipt must be fresh persistent storage.')
    parent = self.receipt.parent.stat()
    if self.receipt.parent.is_symlink() or parent.st_uid != os.geteuid() or parent.st_mode & 18:
        raise RelationViolationError('Task carry receipt parent is not owner-controlled.')
    originals = self.receipt.with_name(self.receipt.name + '.originals')
    if originals.exists() or originals.is_symlink():
        raise RelationViolationError('Existing preimages prohibit another carry attempt.')
    environment = dict(os.environ)
    environment.pop('PYTHONPATH', None)
    subprocess.run([self.original_python, Path(__file__).with_name('read_original_task_preimage.py'), self.wire_root, self.wire_root_id], env=environment, stdout=subprocess.DEVNULL, check=True)

def require_selection(self, snapshot, owners):
    live = {thread.name for thread in OwnerRestartRequest().threads(snapshot)}
    if {thread.name for thread in owners} != live:
        raise RelationViolationError('Thread retirement requires the complete live batch')
    if not self.receipt.is_absolute() or self.receipt.exists() or self.receipt.is_symlink():
        raise RelationViolationError('Thread retirement requires a fresh private receipt')
    parent = self.receipt.parent.stat()
    if parent.st_uid != os.geteuid() or parent.st_mode & 63:
        raise RelationViolationError('Thread retirement receipt directory must be owner-only')
    if self.originals.exists() or self.originals.is_symlink():
        raise RelationViolationError('Original recovery custody forbids repeating retirement')
